     \"Sharada\",\n        \"Shrd\",\n        \"Shavian\",\n        \"Shaw\",\n        \"Siddham\",\n        \"Sidd\",\n        \"SignWriting\",\n        \"Sgnw\",\n        \"Sinhala\",\n        \"Sinh\",\n        \"Sora_Sompeng\",\n        \"Sora\",\n        \"Soyombo\",\n        \"Soyo\",\n        \"Sundanese\",\n        \"Sund\",\n        \"Syloti_Nagri\",\n        \"Sylo\",\n        \"Syriac\",\n        \"Syrc\",\n        \"Tagalog\",\n        \"Tglg\",\n        \"Tagbanwa\",\n        \"Tagb\",\n        \"Tai_Le\",\n        \"Tale\",\n        \"Tai_Tham\",\n        \"Lana\",\n        \"Tai_Viet\",\n        \"Tavt\",\n        \"Takri\",\n        \"Takr\",\n        \"Tamil\",\n        \"Taml\",\n        \"Tangut\",\n        \"Tang\",\n        \"Telugu\",\n        \"Telu\",\n        \"Thaana\",\n        \"Thaa\",\n        \"Thai\",\n        \"Tibetan\",\n        \"Tibt\",\n        \"Tifinagh\",\n        \"Tfng\",\n        \"Tirhuta\",\n        \"Tirh\",\n        \"Ugaritic\",\n        \"Ugar\",\n        \"Vai\",\n        \"Vaii\",\n        \"Warang_Citi\",\n        \"Wara\",\n        \"Yi\",\n        \"Yiii\",\n        \"Zanabazar_Square\",\n        \"Zanb\",\n    ]),\n}\n\nPropertyData.gc = PropertyData.General_Category\nPropertyData.sc = PropertyData.Script_Extensions = PropertyData.scx =\n    PropertyData.Script\n\nexport { PropertyData }\n","export { isIdContinue, isIdStart } from \"./ids\"\nexport { PropertyData } from \"./property-data\"\n\nexport const Null = 0x00\nexport const Backspace = 0x08\nexport const CharacterTabulation = 0x09\nexport const LineFeed = 0x0a\nexport const LineTabulation = 0x0b\nexport const FormFeed = 0x0c\nexport const CarriageReturn = 0x0d\nexport const ExclamationMark = 0x21\nexport const DollarSign = 0x24\nexport const LeftParenthesis = 0x28\nexport const RightParenthesis = 0x29\nexport const Asterisk = 0x2a\nexport const PlusSign = 0x2b\nexport const Comma = 0x2c\nexport const HyphenMinus = 0x2d\nexport const FullStop = 0x2e\nexport const Solidus = 0x2f\nexport const DigitZero = 0x30\nexport const DigitOne = 0x31\nexport const DigitSeven = 0x37\nexport const DigitNine = 0x39\nexport const Colon = 0x3a\nexport const LessThanSign = 0x3c\nexport const EqualsSign = 0x3d\nexport const GreaterThanSign = 0x3e\nexport const QuestionMark = 0x3f\nexport const LatinCapitalLetterA = 0x41\nexport const LatinCapitalLetterB = 0x42\nexport const LatinCapitalLetterD = 0x44\nexport const LatinCapitalLetterF = 0x46\nexport const LatinCapitalLetterP = 0x50\nexport const LatinCapitalLetterS = 0x53\nexport const LatinCapitalLetterW = 0x57\nexport const LatinCapitalLetterZ = 0x5a\nexport const LowLine = 0x5f\nexport const LatinSmallLetterA = 0x61\nexport const LatinSmallLetterB = 0x62\nexport const LatinSmallLetterC = 0x63\nexport const LatinSmallLetterD = 0x64\nexport const LatinSmallLetterF = 0x66\nexport const LatinSmallLetterG = 0x67\nexport const LatinSmallLetterI = 0x69\nexport const LatinSmallLetterK = 0x6b\nexport const LatinSmallLetterM = 0x6d\nexport const LatinSmallLetterN = 0x6e\nexport const LatinSmallLetterP = 0x70\nexport const LatinSmallLetterR = 0x72\nexport const LatinSmallLetterS = 0x73\nexport const LatinSmallLetterT = 0x74\nexport const LatinSmallLetterU = 0x75\nexport const LatinSmallLetterV = 0x76\nexport const LatinSmallLetterW = 0x77\nexport const LatinSmallLetterX = 0x78\nexport const LatinSmallLetterY = 0x79\nexport const LatinSmallLetterZ = 0x7a\nexport const LeftSquareBracket = 0x5b\nexport const ReverseSolidus = 0x5c\nexport const RightSquareBracket = 0x5d\nexport const CircumflexAccent = 0x5e\nexport const LeftCurlyBracket = 0x7b\nexport const VerticalLine = 0x7c\nexport const RightCurlyBracket = 0x7d\nexport const ZeroWidthNonJoiner = 0x200c\nexport const ZeroWidthJoiner = 0x200d\nexport const LineSeparator = 0x2028\nexport const ParagraphSeparator = 0x2029\n\nexport const MinCodePoint = 0x00\nexport const MaxCodePoint = 0x10ffff\n\nexport function isLatinLetter(code: number): boolean {\n    return (\n        (code >= LatinCapitalLetterA && code <= LatinCapitalLetterZ) ||\n        (code >= LatinSmallLetterA && code <= LatinSmallLetterZ)\n    )\n}\n\nexport function isDecimalDigit(code: number): boolean {\n    return code >= DigitZero && code <= DigitNine\n}\n\nexport function isOctalDigit(code: number): boolean {\n    return code >= DigitZero && code <= DigitSeven\n}\n\nexport function isHexDigit(code: number): boolean {\n    return (\n        (code >= DigitZero && code <= DigitNine) ||\n        (code >= LatinCapitalLetterA && code <= LatinCapitalLetterF) ||\n        (code >= LatinSmallLetterA && code <= LatinSmallLetterF)\n    )\n}\n\nexport function isLineTerminator(code: number): boolean {\n    return (\n        code === LineFeed ||\n        code === CarriageReturn ||\n        code === LineSeparator ||\n        code === ParagraphSeparator\n    )\n}\n\nexport function isValidUnicode(code: number): boolean {\n    return code >= MinCodePoint && code <= MaxCodePoint\n}\n\nexport function digitToInt(code: number): number {\n    if (code >= LatinSmallLetterA && code <= LatinSmallLetterF) {\n        return code - LatinSmallLetterA + 10\n    }\n    if (code >= LatinCapitalLetterA && code <= LatinCapitalLetterF) {\n        return code - LatinCapitalLetterA + 10\n    }\n    return code - DigitZero\n}\n","const legacyImpl = {\n    at(s: string, end: number, i: number): number {\n        return i < end ? s.charCodeAt(i) : -1\n    },\n    width(c: number): number {\n        return 1\n    },\n}\nconst unicodeImpl = {\n    at(s: string, end: number, i: number): number {\n        return i < end ? s.codePointAt(i)! : -1\n    },\n    width(c: number): number {\n        return c > 0xffff ? 2 : 1\n    },\n}\n\nexport class Reader {\n    private _impl = legacyImpl\n    private _s = \"\"\n    private _i = 0\n    private _end = 0\n    private _cp1: number = -1\n    private _w1 = 1\n    private _cp2: number = -1\n    private _w2 = 1\n    private _cp3: number = -1\n    private _w3 = 1\n    private _cp4: number = -1\n\n    public get source(): string {\n        return this._s\n    }\n\n    public get index(): number {\n        return this._i\n    }\n\n    public get currentCodePoint(): number {\n        return this._cp1\n    }\n\n    public get nextCodePoint(): number {\n        return this._cp2\n    }\n\n    public get nextCodePoint2(): number {\n        return this._cp3\n    }\n\n    public get nextCodePoint3(): number {\n        return this._cp4\n    }\n\n    public reset(\n        source: string,\n        start: number,\n        end: number,\n        uFlag: boolean,\n    ): void {\n        this._impl = uFlag ? unicodeImpl : legacyImpl\n        this._s = source\n        this._end = end\n        this.rewind(start)\n    }\n\n    public rewind(index: number): void {\n        const impl = this._impl\n        this._i = index\n        this._cp1 = impl.at(this._s, this._end, index)\n        this._w1 = impl.width(this._cp1)\n        this._cp2 = impl.at(this._s, this._end, index + this._w1)\n        this._w2 = impl.width(this._cp2)\n        this._cp3 = impl.at(this._s, this._end, index + this._w1 + this._w2)\n        this._w3 = impl.width(this._cp3)\n        this._cp4 = impl.at(\n            this._s,\n            this._end,\n            index + this._w1 + this._w2 + this._w3,\n        )\n    }\n\n    public advance(): void {\n        if (this._cp1 !== -1) {\n            const impl = this._impl\n            this._i += this._w1\n            this._cp1 = this._cp2\n            this._w1 = this._w2\n            this._cp2 = this._cp3\n            this._w2 = impl.width(this._cp2)\n            this._cp3 = this._cp4\n            this._w3 = impl.width(this._cp3)\n            this._cp4 = impl.at(\n                this._s,\n                this._end,\n                this._i + this._w1 + this._w2 + this._w3,\n            )\n        }\n    }\n\n    public eat(cp: number): boolean {\n        if (this._cp1 === cp) {\n            this.advance()\n            return true\n        }\n        return false\n    }\n\n    public eat2(cp1: number, cp2: number): boolean {\n        if (this._cp1 === cp1 && this._cp2 === cp2) {\n            this.advance()\n            this.advance()\n            return true\n        }\n        return false\n    }\n\n    public eat3(cp1: number, cp2: number, cp3: number): boolean {\n        if (this._cp1 === cp1 && this._cp2 === cp2 && this._cp3 === cp3) {\n            this.advance()\n            this.advance()\n            this.advance()\n            return true\n        }\n        return false\n    }\n}\n","export class RegExpSyntaxError extends SyntaxError {\n    public index: number\n    public constructor(\n        source: string,\n        uFlag: boolean,\n        index: number,\n        message: string,\n    ) {\n        /*eslint-disable no-param-reassign */\n        if (source) {\n            if (source[0] !== \"/\") {\n                source = `/${source}/${uFlag ? \"u\" : \"\"}`\n            }\n            source = `: ${source}`\n        }\n        /*eslint-enable no-param-reassign */\n\n        super(`Invalid regular expression${source}: ${message}`)\n        this.index = index\n    }\n}\n","import { Reader } from \"./reader\"\nimport { RegExpSyntaxError } from \"./regexp-syntax-error\"\nimport {\n    Asterisk,\n    Backspace,\n    CarriageReturn,\n    CharacterTabulation,\n    CircumflexAccent,\n    Colon,\n    Comma,\n    DigitNine,\n    DigitOne,\n    digitToInt,\n    DigitZero,\n    DollarSign,\n    EqualsSign,\n    ExclamationMark,\n    FormFeed,\n    FullStop,\n    GreaterThanSign,\n    HyphenMinus,\n    isDecimalDigit,\n    isHexDigit,\n    isIdContinue,\n    isIdStart,\n    isLatinLetter,\n    isLineTerminator,\n    isOctalDigit,\n    isValidUnicode,\n    LatinCapitalLetterB,\n    LatinCapitalLetterD,\n    LatinCapitalLetterP,\n    LatinCapitalLetterS,\n    LatinCapitalLetterW,\n    LatinSmallLetterB,\n    LatinSmallLetterC,\n    LatinSmallLetterD,\n    LatinSmallLetterF,\n    LatinSmallLetterG,\n    LatinSmallLetterI,\n    LatinSmallLetterK,\n    LatinSmallLetterM,\n    LatinSmallLetterN,\n    LatinSmallLetterP,\n    LatinSmallLetterR,\n    LatinSmallLetterS,\n    LatinSmallLetterT,\n    LatinSmallLetterU,\n    LatinSmallLetterV,\n    LatinSmallLetterW,\n    LatinSmallLetterX,\n    LatinSmallLetterY,\n    LeftCurlyBracket,\n    LeftParenthesis,\n    LeftSquareBracket,\n    LessThanSign,\n    LineFeed,\n    LineTabulation,\n    LowLine,\n    PlusSign,\n    PropertyData,\n    QuestionMark,\n    ReverseSolidus,\n    RightCurlyBracket,\n    RightParenthesis,\n    RightSquareBracket,\n    Solidus,\n    VerticalLine,\n    ZeroWidthJoiner,\n    ZeroWidthNonJoiner,\n} from \"./unicode\"\n\nfunction isSyntaxCharacter(cp: number): boolean {\n    return (\n        cp === CircumflexAccent ||\n        cp === DollarSign ||\n        cp === ReverseSolidus ||\n        cp === FullStop ||\n        cp === Asterisk ||\n        cp === PlusSign ||\n        cp === QuestionMark ||\n        cp === LeftParenthesis ||\n        cp === RightParenthesis ||\n        cp === LeftSquareBracket ||\n        cp === RightSquareBracket ||\n        cp === LeftCurlyBracket ||\n        cp === RightCurlyBracket ||\n        cp === VerticalLine\n    )\n}\n\nfunction isRegExpIdentifierStart(cp: number): boolean {\n    return isIdStart(cp) || cp === DollarSign || cp === LowLine\n}\n\nfunction isRegExpIdentifierPart(cp: number): boolean {\n    return (\n        isIdContinue(cp) ||\n        cp === DollarSign ||\n        cp === LowLine ||\n        cp === ZeroWidthNonJoiner ||\n        cp === ZeroWidthJoiner\n    )\n}\n\nfunction isUnicodePropertyNameCharacter(cp: number): boolean {\n    return isLatinLetter(cp) || cp === LowLine\n}\n\nfunction isUnicodePropertyValueCharacter(cp: number): boolean {\n    return isUnicodePropertyNameCharacter(cp) || isDecimalDigit(cp)\n}\n\nfunction isValidUnicodeProperty(name: string, value: string): boolean {\n    //eslint-disable-next-line no-prot